import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final long M = 1000000007L;
        // Reads integers n and k
        int[] input = readInts(sc);
        int n = input[0], k = input[1];

        int[] v = new int[] {0, 0};
        int[] xs = readInts(sc);
        for (int x : xs) {
            if (x > 50)
                v[1]++;
            else
                v[0]++;
        }
        k /= 50;

        int size = 8192;
        long[] t = new long[size];
        long[] c = new long[size];
        int[] q = new int[size];
        int[] h = new int[1]; // Using array for mutability in lambda
        int[] u = new int[1];

        long[] dist = new long[size];
        int[] visited = new int[size];
        int[] start_Node = new int[] { pack(0, v[0], v[1]) };
        int startNode = start_Node[0];

        Arrays.fill(t, M);
        Arrays.fill(c, 0);
        Arrays.fill(dist, M);
        Arrays.fill(visited, 0);

        t[startNode] = 0;
        c[startNode] = 1;
        q[0] = startNode;
        h[0] = 0;

        int[][] d = new int[64][64];
        for (int i = 0; i < 64; i++) {
            Arrays.fill(d[i], 0);
        }
        for (int i = 0; i < 64; i++) {
            d[i][0] = 1;
            d[i][i] = 1;
        }
        for (int i = 2; i < 64; i++) {
            for (int j = 1; j < i; j++) {
                d[i][j] = (d[i - 1][j - 1] + d[i - 1][j]) % (int) M;
            }
        }

        while (h[0] < size) {
            u[0] = q[h[0]];
            h[0]++;
            int x = u[0] / (3600);
            int y = (u[0] / 60) % 60;
            int z = u[0] % 60;
            for (int i = 0; i <= y; i++) {
                for (int j = 0; j <= z; j++) {
                    if ((i + j) != 0 && (i + j) * 2 <= k) {
                        int w = pack(1 - x, v[0] - y + i, v[1] - z + j);
                        if (t[w] >= M) {
                            t[w] = t[u[0]] + 1;
                            if (size - 1 >= h[0]) {
                                q[h[0]] = w;
                            }
                        }
                        if (t[w] == t[u[0]] + 1) {
                            c[w] = (c[w] + c[u[0]] * d[y][i] * d[z][j]) % M;
                        }
                    }
                }
            }
        }

        int answerNode = pack(1, v[0], v[1]);
        if (t[answerNode] >= M) {
            System.out.println(-1);
        } else {
            System.out.println(t[answerNode]);
        }
        System.out.println(c[answerNode]);

        sc.close();
    }

    static int[] readInts(Scanner sc) {
        String line = sc.nextLine();
        String[] parts = line.trim().split("\\s+");
        int[] res = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            res[i] = Integer.parseInt(parts[i]);
        }
        return res;
    }

    static int pack(int a, int b, int c) {
        return (a << 12) | (b << 6) | c;
    }
